const toArr = (r: any): any[] => {
  if (Array.isArray(r)) return r;
  for (const k of ["items", "issues", "comments", "data", "results"]) {
    if (r && Array.isArray(r[k])) return r[k];
  }
  return [];
};
const loginOf = (x: any): string | undefined => {
  const u = x?.user ?? x?.author ?? x;
  return typeof u === "string" ? u : u?.login;
};

// 1. Collect all open issues labeled perf (paginate).
const issues: any[] = [];
let raw: any = null;
for (let page = 1; page <= 50; page++) {
  const r = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  if (page === 1) raw = r;
  const arr = toArr(r);
  if (arr.length === 0) break;
  issues.push(...arr);
}

// Keep only issues that really carry the perf label (defensive against filter quirks).
const perfIssues = issues.filter((i: any) => {
  const labels = (i.labels ?? []).map((l: any) => (typeof l === "string" ? l : l?.name));
  return labels.includes("perf") && (i.state === undefined || i.state === "open");
});
const numbers = [...new Set(perfIssues.map((i: any) => i.number))];

if (numbers.length === 0) {
  return { note: "no issues found", sample: JSON.stringify(raw).slice(0, 1500) };
}

// 2. For each issue, collect distinct commenters across all comment pages.
const countByUser: Record<string, Set<number>> = {};
for (const n of numbers) {
  const commenters = new Set<string>();
  for (let page = 1; page <= 50; page++) {
    const r = await tools.list_comments({ repo: "acme/web", number: n, page });
    const arr = toArr(r);
    if (arr.length === 0) break;
    for (const c of arr) {
      const l = loginOf(c);
      if (l) commenters.add(l);
    }
    if (arr.length < 50) break;
  }
  for (const l of commenters) {
    (countByUser[l] ??= new Set()).add(n);
  }
}

const result = Object.entries(countByUser)
  .filter(([, s]) => s.size >= 4)
  .map(([login]) => login)
  .sort();

return { perfIssueCount: numbers.length, result, counts: Object.fromEntries(Object.entries(countByUser).map(([k, s]) => [k, s.size])) };
